import{_ as e,o as a,c as o,ah as n}from"./chunks/framework.BMM80GXQ.js";const u=JSON.parse('{"title":"Magic AI","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/magic/magic-ai.md","filePath":"2.0/magic/magic-ai.md","lastUpdated":1775051911000}'),i={name:"2.0/magic/magic-ai.md"};function r(s,t,l,c,g,d){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="magic-ai" tabindex="-1">Magic AI <a class="header-anchor" href="#magic-ai" aria-label="Permalink to &quot;Magic AI&quot;">​</a></h1><p>Magic AI is the ultimate tool for professionals in diverse fields looking to enhance their efficiency.</p><p>UnoPim integrates Magic AI, using artificial intelligence for product information management. Magic AI leverages advanced LLM (Large Language Model) technology to automate content creation, translation, and product enrichment.</p><h2 id="content-generation" tabindex="-1">Content Generation <a class="header-anchor" href="#content-generation" aria-label="Permalink to &quot;Content Generation&quot;">​</a></h2><p>With Magic AI, you can effortlessly generate engaging <strong>Products &amp; Categories</strong> content — including product names, descriptions, SEO metadata, and more.</p><p>Say goodbye to time-consuming manual content creation as Magic AI crafts compelling and unique descriptions, saving you valuable time and effort.</p><h3 id="supported-ai-providers" tabindex="-1">Supported AI Providers <a class="header-anchor" href="#supported-ai-providers" aria-label="Permalink to &quot;Supported AI Providers&quot;">​</a></h3><p>UnoPim provides native support for multiple AI providers through its <strong>Multi-Platform MagicAI</strong> system. You can configure one or more providers with encrypted credential storage for secure API key management.</p><p><strong>A) For Content — UnoPim supports these AI providers:</strong></p><ul><li><strong>OpenAI</strong> – gpt-4o, gpt-4o-mini, gpt-3.5-turbo, dall-e-2, dall-e-3</li><li><strong>Ollama</strong> – llama2, llama3, mistral, qwen, deepseek-coder, phi, llava</li><li><strong>Gemini</strong> – gemini-2.5-pro, gemini-2.5-flash, gemini-2.0-flash, gemini-1.5-flash-latest, gemini-1.5-pro</li><li><strong>Groq (xAI)</strong> – deepseek-r1-distill-llama-70b, llama-3.1-8b-instant, openai/gpt-oss-120b, openai/gpt-oss-20b, groq/compound, qwen/qwen3-32b, moonshotai/kimi-k2-instruct-0905</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>All providers are managed through a unified <strong>LaravelAiAdapter</strong> implementation. You can switch providers without changing your workflow.</p></div><h2 id="how-to-generate-text-content-with-ai" tabindex="-1">How to Generate Text Content with AI <a class="header-anchor" href="#how-to-generate-text-content-with-ai" aria-label="Permalink to &quot;How to Generate Text Content with AI&quot;">​</a></h2><p>Follow these steps to generate text content for your products using Magic AI:</p><ol><li>Navigate to <strong>Catalog &gt;&gt; Products</strong> and click <strong>Edit</strong> on a product.</li><li>Find a text field that supports AI generation (Name, Short Description, Description, Meta Title, Meta Description, etc.).</li><li>Click the <strong>Magic AI icon</strong> (sparkle/wand icon) next to the field.</li><li>The AI generates content based on: <ul><li>The configured <strong>Prompt</strong> for that field type (from Magic AI &gt;&gt; Prompts).</li><li>The product&#39;s existing data (name, category, attributes).</li><li>The active <strong>System Prompt</strong> personality.</li></ul></li><li>The generated content appears in the field.</li><li>Review and edit the generated content as needed.</li><li>Click <strong>Save Product</strong> to keep the changes.</li></ol><p>You can also generate content for categories by navigating to a category edit page and using the same AI icon on supported fields.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Configure your preferred AI provider and model in <strong>Magic AI &gt;&gt; Settings &gt;&gt; Text Generation</strong> before using this feature. Choose a platform that balances quality and cost for your needs.</p></div><h2 id="how-to-generate-images-with-ai" tabindex="-1">How to Generate Images with AI <a class="header-anchor" href="#how-to-generate-images-with-ai" aria-label="Permalink to &quot;How to Generate Images with AI&quot;">​</a></h2><p>Follow these steps to generate product images using Magic AI:</p><ol><li>Navigate to <strong>Catalog &gt;&gt; Products</strong> and click <strong>Edit</strong> on a product.</li><li>Find an Image or Gallery attribute.</li><li>Click the <strong>Magic AI icon</strong> next to the image field.</li><li>Enter a description of the image you want to generate (or the system uses the configured Image prompt from Magic AI &gt;&gt; Prompts).</li><li>The AI generates a product image based on the description.</li><li>Review the generated image.</li><li>Click to accept and attach it to the product.</li><li>Click <strong>Save Product</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Image generation requires an AI platform that supports image creation (OpenAI with DALL-E, Gemini, or xAI). Configure your image platform in <strong>Magic AI &gt;&gt; Settings &gt;&gt; Image Generation</strong>.</p></div><h2 id="custom-prompts" tabindex="-1">Custom Prompts <a class="header-anchor" href="#custom-prompts" aria-label="Permalink to &quot;Custom Prompts&quot;">​</a></h2><p>Magic AI supports <strong>Custom Prompts</strong> for content generation. You can define specific instructions that guide the AI when generating content for your products and categories.</p><p>For example, you can set prompts like:</p><ul><li>&quot;Generate a professional product description for an electronics store&quot;</li><li>&quot;Write SEO-optimized content with keywords for fashion products&quot;</li><li>&quot;Create a brief 50-word summary suitable for mobile displays&quot;</li></ul><h2 id="system-prompt-management" tabindex="-1">System Prompt Management <a class="header-anchor" href="#system-prompt-management" aria-label="Permalink to &quot;System Prompt Management&quot;">​</a></h2><p><strong>System Prompts</strong> allow you to configure the overall behavior and personality of the AI across your entire PIM system. This ensures consistent tone, style, and formatting across all AI-generated content.</p><p>To manage system prompts, navigate to <strong>Configuration &gt;&gt; Magic AI &gt;&gt; System Prompt</strong>.</p><h2 id="magic-image" tabindex="-1">Magic Image <a class="header-anchor" href="#magic-image" aria-label="Permalink to &quot;Magic Image&quot;">​</a></h2><p>Magic AI includes an <strong>Image Generation</strong> feature powered by DALL-E (OpenAI). You can generate product images directly from text descriptions.</p><p>To use Magic Image:</p><ol><li>Navigate to a product edit page</li><li>Click on the <strong>Magic AI</strong> icon near the image/gallery field</li><li>Enter a description of the image you want to generate</li><li>Select the AI model (dall-e-2 or dall-e-3)</li><li>Click <strong>Generate</strong> to create the image</li></ol><h2 id="auto-translation" tabindex="-1">Auto-Translation <a class="header-anchor" href="#auto-translation" aria-label="Permalink to &quot;Auto-Translation&quot;">​</a></h2><p>Magic AI provides <strong>automatic translation</strong> of product data when creating or updating products. When you save a product, Magic AI can automatically translate all locale-specific fields (name, description, etc.) to all configured locales in your channels.</p><p>This feature ensures your product information is available in every language without manual translation effort.</p><h3 id="translation-settings-ui" tabindex="-1">Translation Settings UI <a class="header-anchor" href="#translation-settings-ui" aria-label="Permalink to &quot;Translation Settings UI&quot;">​</a></h3><p>The Translation section is configured on the Magic AI Settings page at <strong>Magic AI &gt;&gt; Settings</strong>. Navigate there and scroll to the <strong>Translation</strong> section. The following fields are available:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Enabled</strong></td><td>Toggle to enable or disable AI-powered translation</td></tr><tr><td><strong>Default Platform</strong></td><td>Select the AI platform to use for translations. You can choose a different provider than your content generation platform, allowing you to optimize for cost or speed</td></tr><tr><td><strong>Translation Model</strong></td><td>Select the specific model for translation tasks. This is independent of the text generation model</td></tr><tr><td><strong>Replace Existing Value</strong></td><td>When enabled, existing translations in target locales are overwritten with new AI-generated translations. When disabled, only empty locale fields are filled</td></tr><tr><td><strong>Source Channel</strong></td><td>The channel whose content serves as the translation source</td></tr><tr><td><strong>Target Channel</strong></td><td>The channel that receives the translated content</td></tr><tr><td><strong>Source Locale</strong></td><td>The locale to translate from (e.g., en_US)</td></tr><tr><td><strong>Target Locales</strong></td><td>A multi-select dropdown where you choose all the locales you want to translate into</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use the <strong>Replace Existing Value</strong> toggle carefully. When turned off, only empty fields are translated, preserving any manual translations you have already made. Turn it on only when you want to regenerate all translations from scratch.</p></div><h3 id="how-auto-translation-works" tabindex="-1">How Auto-Translation Works <a class="header-anchor" href="#how-auto-translation-works" aria-label="Permalink to &quot;How Auto-Translation Works&quot;">​</a></h3><p>When auto-translation is enabled and a product is created or updated, UnoPim automatically translates all locale-specific fields (name, short description, description, meta title, meta description, meta keywords, etc.) to the configured target locales using the selected AI provider and model.</p><p>The translation respects channel and locale assignments, so only the locales assigned to the target channel are populated.</p><h3 id="manual-translation-via-locale-switcher" tabindex="-1">Manual Translation via Locale Switcher <a class="header-anchor" href="#manual-translation-via-locale-switcher" aria-label="Permalink to &quot;Manual Translation via Locale Switcher&quot;">​</a></h3><p>You can also translate product content manually by switching locales on the product edit page. Use the <strong>locale switcher</strong> dropdown at the top of the product edit form to switch between locales. Attributes that support per-locale values display a <strong>locale badge</strong> indicating which locale&#39;s value you are currently editing.</p><p>When you switch to a target locale, you can either type translations manually or let Magic AI generate them for that specific locale.</p><h3 id="ai-powered-translation-command" tabindex="-1">AI-Powered Translation Command <a class="header-anchor" href="#ai-powered-translation-command" aria-label="Permalink to &quot;AI-Powered Translation Command&quot;">​</a></h3><p>For bulk translation of existing data, UnoPim v2.0 includes an <strong>AI-Powered Translation Command</strong> that uses Magic AI to bulk translate missing locale keys across all 32 non-English locales. This can automatically translate thousands of previously untranslated keys across all packages.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The auto-translation feature works with any configured AI provider and respects your locale settings in each channel. For high-volume translation workloads, consider using a faster or cheaper provider dedicated to translations while keeping a premium provider for content generation.</p></div><h2 id="ai-powered-search" tabindex="-1">AI-Powered Search <a class="header-anchor" href="#ai-powered-search" aria-label="Permalink to &quot;AI-Powered Search&quot;">​</a></h2><p>UnoPim v2.0 introduces <strong>AI-Powered Search</strong> that uses embedding similarity and semantic ranking to deliver more intelligent search results. Instead of simple keyword matching, the search understands the meaning behind your queries.</p><p>Key capabilities:</p><ul><li><strong>Embedding Similarity Service</strong> — Converts product data into vector embeddings for semantic comparison</li><li><strong>Semantic Ranking Service</strong> — Ranks search results by relevance using AI understanding</li></ul><h2 id="auto-enrichment" tabindex="-1">Auto-Enrichment <a class="header-anchor" href="#auto-enrichment" aria-label="Permalink to &quot;Auto-Enrichment&quot;">​</a></h2><p>The <strong>Auto-Enrichment</strong> feature automatically fills in missing product information such as descriptions and SEO fields. When enabled, Magic AI analyzes your product data and generates content for empty fields.</p><p>This is especially useful for:</p><ul><li>Bulk-imported products that lack descriptions</li><li>Products missing SEO metadata (meta title, meta description, keywords)</li><li>Incomplete product records flagged by the completeness system</li></ul><h2 id="ai-in-agentic-pim-chat" tabindex="-1">AI in Agentic PIM Chat <a class="header-anchor" href="#ai-in-agentic-pim-chat" aria-label="Permalink to &quot;AI in Agentic PIM Chat&quot;">​</a></h2><p>The AI Agent Chat (Agentic PIM) also provides <strong>Generate Content</strong> and <strong>Generate Image</strong> tools. You can ask it in natural language to perform content and image generation without navigating through the UI.</p><p>Example prompts you can use in the chat:</p><ul><li>&quot;Generate a product description for SKU SHOE-100&quot;</li><li>&quot;Create an image for product Nike Air Max&quot;</li></ul><p>The agent uses the same configured AI providers and prompts behind the scenes, so your settings from <strong>Magic AI &gt;&gt; Settings</strong> and <strong>Magic AI &gt;&gt; Prompts</strong> apply automatically.</p>',60)])])}const h=e(i,[["render",r]]);export{u as __pageData,h as default};
